mapper.select:
select count(1)
from alert_breaker_policy
where name = #{name}
  and id != #{id}

select count(1)
from alert_event_handler_breaker_policy_rel
where policy_id = #{value}

select a.id, a.event_handler_id as eventHandlerId, a.policy_id as policyId, b.name as policyName, b.handler as policyHandler, b.config as policyConfigStr, a.sort from alert_event_handler_breaker_policy_rel a left join alert_breaker_policy b on a.policy_id = b.id where a.event_handler_id in
#{eventHandlerId}
order by a.event_handler_id, a.sort

select count(1)
from alert_breaker_collect_item
where state_id = #{stateId}
  and alert_id = #{alertId}

select count(1)
from alert_breaker_collect_item
where state_id = #{value}

select alert_id
from alert_breaker_collect_item
where state_id = #{stateId}
  and alert_id >= #{baselineAlertId}
order by id

select a.id, a.policy_id as policyId, a.event_handler_id as eventHandlerId, a.unique_key as uniqueKey, a.state, a.window_start as windowStart, a.window_end as windowEnd, a.trigger_count as triggerCount, a.open_time as openTime, a.open_until as openUntil, a.last_trigger_time as lastTriggerTime, a.skip_count as skipCount, a.data from alert_breaker_state a left join alert_breaker_policy b on a.policy_id = b.id where a.state in ('OPEN', 'COLLECTING') and a.open_until is not null and a.open_until <= now(3) and b.is_active = 1
and b.handler = #{handler}
order by a.open_until, a.id limit #{limit}

select a.id, a.policy_id as policyId, a.event_handler_id as eventHandlerId, a.unique_key as uniqueKey, a.state, a.window_start as windowStart, a.window_end as windowEnd, a.trigger_count as triggerCount, a.open_time as openTime, a.open_until as openUntil, a.last_trigger_time as lastTriggerTime, a.skip_count as skipCount, a.data from alert_breaker_state a left join alert_breaker_policy b on a.policy_id = b.id where a.state in ('OPEN', 'COLLECTING') and a.open_until is not null and b.is_active = 1 and a.id > #{lastId}
and b.handler = #{handler}
order by a.id limit #{limit}

select count(1)
from alert_breaker_state
where policy_id = #{policyId}

select a.id, a.policy_id as policyId, b.name as policyName, b.handler as policyHandler, b.config as policyConfigStr, a.state_id as stateId, c.data as stateDataStr, a.alert_id as alertId, a.event_handler_audit_id as eventHandlerAuditId, a.start_time as startTime, a.end_time as endTime, a.status, a.error from alert_breaker_audit a left join alert_breaker_policy b on a.policy_id = b.id left join alert_breaker_state c on a.state_id = c.id where a.event_handler_audit_id in
#{eventHandlerAuditId}
order by a.id
